def longest_common_subsequence_three(str1: str, str2: str, str3: str) -> str:
    """
    Returns the longest common subsequence (LCS) of three strings.
    """
    m, n, p = len(str1), len(str2), len(str3)

    # dp[i][j][k] stores the length of LCS for prefixes str1[:i], str2[:j], str3[:k]
    dp = [[[0] * (p + 1) for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, p + 1):
                if str1[i-1] == str2[j-1] == str3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # Backtrack to find the LCS string
    i, j, k = m, n, p
    lcs_chars = []

    while i > 0 and j > 0 and k > 0:
        if str1[i-1] == str2[j-1] == str3[k-1]:
            lcs_chars.append(str1[i-1])
            i -= 1
            j -= 1
            k -= 1
        else:
            if dp[i-1][j][k] >= dp[i][j-1][k] and dp[i-1][j][k] >= dp[i][j][k-1]:
                i -= 1
            elif dp[i][j-1][k] >= dp[i-1][j][k] and dp[i][j-1][k] >= dp[i][j][k-1]:
                j -= 1
            else:
                k -= 1

    return ''.join(reversed(lcs_chars))
