def largest_divisible_subset(nums):
    if not nums:
        return []

    nums.sort()
    n = len(nums)
    dp = [1] * n
    prev = [-1] * n

    max_len = 1
    max_index = 0

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j
        if dp[i] > max_len:
            max_len = dp[i]
            max_index = i

    result = []
    i = max_index
    while i >= 0:
        result.append(nums[i])
        i = prev[i]

    return result[::-1]
