def find_triplet(arr, target_sum):
    """
    Returns True if there exists a triplet in the array whose sum equals target_sum.
    Otherwise returns False.
    """
    n = len(arr)
    if n < 3:
        return False

    arr.sort()

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target_sum:
                return True
            elif current_sum < target_sum:
                left += 1
            else:
                right -= 1

    return False
