def is_nested_subset(nested_list1, nested_list2):
    """
    Check if nested_list1 is a subset of nested_list2.
    Both are lists that may contain other lists or non-list elements.
    """
    def normalize(item):
        """Convert list to tuple recursively for hashable comparison."""
        if isinstance(item, list):
            return tuple(normalize(sub) for sub in item)
        return item

    def flatten_to_set(nested):
        """Recursively collect all elements as normalized tuples."""
        result = set()
        for item in nested:
            if isinstance(item, list):
                result.add(normalize(item))
                result.update(flatten_to_set(item))
            else:
                result.add(item)
        return result

    set1 = flatten_to_set(nested_list1)
    set2 = flatten_to_set(nested_list2)
    return set1.issubset(set2)
