def remove_nested_record(tup, key):
    """
    Remove a nested record (dictionary) from a tuple based on a key.

    Args:
        tup: The input tuple possibly containing nested dictionaries
        key: The key to remove from nested dictionaries

    Returns:
        A new tuple with the specified key removed from all nested dictionaries
    """
    result = []
    for item in tup:
        if isinstance(item, dict):
            # Create a new dict without the specified key
            new_dict = {k: v for k, v in item.items() if k != key}
            result.append(new_dict)
        elif isinstance(item, tuple):
            # Recursively process nested tuples
            result.append(remove_nested_record(item, key))
        else:
            result.append(item)
    return tuple(result)
