def longest_chain(pairs):
    """
    Returns the length of the longest chain that can be formed from the given set of pairs.
    Each pair is (a, b) where a < b, and a chain is a sequence of pairs (p1, p2, ..., pk)
    such that for each i, p1[i][1] < p2[i][0].
    """
    if not pairs:
        return 0

    # Sort pairs by the second element (end value)
    sorted_pairs = sorted(pairs, key=lambda x: x[1])

    # Initialize dp array where dp[i] = length of longest chain ending at pair i
    n = len(sorted_pairs)
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if sorted_pairs[j][1] < sorted_pairs[i][0]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
