def sum_of_prime_divisors(n):
    """Return the sum of all prime divisors of a given number n."""
    total = 0
    # Handle factor 2
    if n % 2 == 0:
        total += 2
        while n % 2 == 0:
            n //= 2
    # Check odd factors from 3 upwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            total += factor
            while n % factor == 0:
                n //= factor
