        while n % 2 == 0:
            n //= 2
    # Check odd factors from 3 upwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            total += factor
            while n % factor == 0:
                n //= factor
        factor += 2
    # If n is still greater than 1, it is a prime factor
    if n > 1:
        total += n
    return total
