def minFallingPathSum(A):
    n = len(A)
    if n == 0:
        return 0

    # Start from the second row and update each cell with the minimum sum to reach it
    for i in range(1, n):
        for j in range(n):
            # The possible previous row columns are j-1, j, j+1 (if within bounds)
            prev_min = A[i-1][j]
            if j > 0:
                prev_min = min(prev_min, A[i-1][j-1])
            if j < n - 1:
                prev_min = min(prev_min, A[i-1][j+1])
            A[i][j] += prev_min

    # The answer is the minimum value in the last row
    return min(A[-1])
