    # cost[i][j] = min changes to make s[i:j+1] palindrome
    cost = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            cost[i][j] = cost[i + 1][j - 1] + (0 if s[i] == s[j] else 1)

    # dp[i][j] = min changes for first i+1 chars into j+1 palindromic substrings
    INF = 10**9
    dp = [[INF] * k for _ in range(n)]

    for i in range(n):
        dp[i][0] = cost[0][i]

    for j in range(1, k):
        for i in range(j, n):
            for m in range(j - 1, i):
                dp[i][j] = min(dp[i][j], dp[m][j - 1] + cost[m + 1][i])

    return dp[n - 1][k - 1]
```

