def find_reversal_segment(n, arr):
    # Find the first position where arr differs from 1,2,...,n
    l = -1
    for i in range(n):
        if arr[i] != i + 1:
            l = i
            break

    # If no difference, the array is already sorted
    if l == -1:
        return (0, 0)

    # Find the first position from the left where the decreasing segment ends
    r = -1
    for i in range(l, n - 1):
        if arr[i] < arr[i + 1]:
            r = i
            break
    else:
        r = n - 1

    # Check if the segment [l, r] is strictly decreasing
    for i in range(l, r):
        if arr[i] < arr[i + 1]:
            return (0, 0)

    # Check if reversing this segment gives the original sorted order
    reversed_segment = list(reversed(arr[l:r+1]))
    expected = list(range(1, n+1))

    # Build the array after reversal
    new_arr = arr[:l] + reversed_segment + arr[r+1:]

    if new_arr == expected:
        return (l + 1, r + 1)  # convert to 1-based indexing
    else:
        return (0, 0)

