    # Check if we can hop from w1 to w2
    # Case 1: deletion
    if len(w1) == len(w2) + 1:
        i = j = 0
        while i < len(w1) and j < len(w2):
            if w1[i] == w2[j]:
                i += 1
                j += 1
            else:
                i += 1
        return j == len(w2)

    # Case 2: replacement
    if len(w1) == len(w2):
        diff_pos = None
        for k in range(len(w1)):
            if w1[k] != w2[k]:
                if diff_pos is not None:
                    return False
                diff_pos = k
        if diff_pos is None:
            return False
        # Check replacement condition
        old_char = w1[diff_pos]
        new_char = w2[diff_pos]
        if new_char <= old_char:
            return False
        # new_char must appear to the right of old_char in w1
        if new_char not in w1[diff_pos+1:]:
            return False
        return True

    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    words = data[1:1+n]

    # Build graph
    graph = defaultdict(list)
    index = {w: i for i, w in enumerate(words)}

    for i in range(n):
        for j in range(n):
            if i != j and can_hop(words[i], words[j]):
                graph[i].append(j)

    # DP for longest path in DAG (since hops always reduce or keep length? 
    # Actually replacement keeps length, but alphabetical order ensures no cycles)
    # We'll use memoization DFS
    memo = {}

    def dfs(u):
        if u in memo:
            return memo[u]
        best = 1
        for v in graph[u]:
            best = max(best, 1 + dfs(v))
        memo[u] = best
        return best

    result = 0
    for i in range(n):
        result = max(result, dfs(i))

    print(result)

if __name__ == "__main__":
    main()
