def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False

    shift_needed = {}

    for i in range(len(s)):
        if s[i] != t[i]:
            diff = (ord(t[i]) - ord(s[i])) % 26
            if diff == 0:
                continue
            # Count how many times we need this shift value
            if diff in shift_needed:
                shift_needed[diff] += 1
            else:
                shift_needed[diff] = 1

    for diff, count in shift_needed.items():
        # The maximum move we can use for this diff is:
        # diff + 26 * (count - 1)
        max_move_needed = diff + 26 * (count - 1)
        if max_move_needed > k:
            return False

    return True
