from typing import List

class Solution:
    def minDeletionSize(self, A: List[str]) -> int:
        n = len(A[0])
        dp = [1] * n  # dp[j] = longest valid subsequence ending at column j

        for j in range(n):
            for i in range(j):
                # check if we can extend the subsequence from column i to column j
                valid = True
                for row in A:
                    if row[i] > row[j]:
                        valid = False
                        break
                if valid:
                    dp[j] = max(dp[j], dp[i] + 1)

        # maximum number of columns we can keep
        max_keep = max(dp)
        # minimum deletions = total columns - max columns we can keep
        return n - max_keep
```

