def count_palindrome_pairs(s):
    n = len(s)
    # is_pal[i][j] = True if substring s[i:j+1] is palindrome
    is_pal = [[False] * n for _ in range(n)]

    # All substrings of length 1 are palindrome
    for i in range(n):
        is_pal[i][i] = True

    # Check substrings of length 2
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            is_pal[i][i + 1] = True

    # Check longer substrings
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and is_pal[i + 1][j - 1]:
                is_pal[i][j] = True

    # end_pal[i] = number of palindromic substrings ending at position i
    end_pal = [0] * n
    for i in range(n):
        count = 0
        for start in range(i + 1):
            if is_pal[start][i]:
                count += 1
        end_pal[i] = count

    # start_pal[i] = number of palindromic substrings starting at position i
    start_pal = [0] * n
    for i in range(n):
        count = 0
        for end in range(i, n):
            if is_pal[i][end]:
                count += 1
        start_pal[i] = count

    # prefix_end_sum[i] = sum of end_pal[0..i]
    prefix_end_sum = [0] * n
    prefix_end_sum[0] = end_pal[0]
    for i in range(1, n):
        prefix_end_sum[i] = prefix_end_sum[i - 1] + end_pal[i]

    total = 0
    # For each possible start of s2, count valid s1 that end before it
    for j in range(1, n):
        # s2 can start at j, s1 must end at j-1 or earlier
        total += prefix_end_sum[j - 1] * start_pal[j]

    return total

