from typing import List

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        # DSU structure
        parent = list(range(n))
        size = [1] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            size[rx] += size[ry]

        # Build connected components
        for i in range(n):
            for j in range(i + 1, n):
                if graph[i][j] == 1:
                    union(i, j)

        # Count infected nodes per component
        infected_count = {}
        for node in initial:
            root = find(node)
            infected_count[root] = infected_count.get(root, 0) + 1

        # Evaluate best node to remove
        best_node = min(initial)
        best_saved = 0

        for node in initial:
            root = find(node)
            if infected_count[root] == 1:
                saved = size[root]
                if saved > best_saved or (saved == best_saved and node < best_node):
                    best_saved = saved
                    best_node = node
            else:
                if best_saved == 0 and node < best_node:
                    best_node = node

        return best_node
