def decodeAtIndex(S: str, K: int) -> str:
    size = 0
    # First, compute the total length of the decoded string
    for ch in S:
        if ch.isdigit():
            size *= int(ch)
        else:
            size += 1

    # Then, work backwards to find the K-th letter
    for ch in reversed(S):
        K %= size
        if K == 0 and ch.isalpha():
            return ch
        if ch.isdigit():
            size //= int(ch)
        else:
            size -= 1
