class Solution:
    def largestComponentSize(self, A: List[int]) -> int:
        # Disjoint Set Union (Union-Find) with path compression and union by size
        parent = {}
        size = {}

        def find(x):
            # Path compression
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # Union by size
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            size[rx] += size[ry]

        # Helper to get prime factors
        def prime_factors(num):
            factors = set()
            # Check 2
            while num % 2 == 0:
                factors.add(2)
                num //= 2
            # Check odd numbers
            f = 3
            while f * f <= num:
                while num % f == 0:
                    factors.add(f)
                    num //= f
                f += 2
            if num > 1:
                factors.add(num)
            return factors

        # Initialize each number as its own set
        for val in A:
            parent[val] = val
            size[val] = 1

        # Map from prime factor to one of the numbers that has it
        prime_to_num = {}

        for val in A:
            for p in prime_factors(val):
                if p in prime_to_num:
                    union(val, prime_to_num[p])
                else:
                    prime_to_num[p] = val

        # Find the largest component size
        comp_size = {}
        for val in A:
            root = find(val)
            comp_size[root] = comp_size.get(root, 0) + 1

        return max(comp_size.values())
