from typing import List
from collections import defaultdict, deque

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        m, n = len(targetGrid), len(targetGrid[0])
        # For each color, find its bounding box
        bounds = {}
        for i in range(m):
            for j in range(n):
                color = targetGrid[i][j]
                if color not in bounds:
                    bounds[color] = [i, i, j, j]  # min_row, max_row, min_col, max_col
                else:
                    bounds[color][0] = min(bounds[color][0], i)
                    bounds[color][1] = max(bounds[color][1], i)
                    bounds[color][2] = min(bounds[color][2], j)
                    bounds[color][3] = max(bounds[color][3], j)

        # Build graph: if color A must be printed before color B
        graph = defaultdict(set)
        indegree = defaultdict(int)
        colors = list(bounds.keys())

        for color in colors:
            min_r, max_r, min_c, max_c = bounds[color]
            for i in range(min_r, max_r + 1):
                for j in range(min_c, max_c + 1):
                    if targetGrid[i][j] != color:
                        if color not in graph[targetGrid[i][j]]:
                            graph[targetGrid[i][j]].add(color)
                            indegree[color] += 1

        # Topological sort (Kahn's algorithm)
        q = deque([c for c in colors if indegree[c] == 0])
        visited_count = 0
        while q:
            c = q.popleft()
            visited_count += 1
            for neighbor in graph[c]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    q.append(neighbor)

        return visited_count == len(colors)
