        colors = list(bounds.keys())

        for color in colors:
            min_r, max_r, min_c, max_c = bounds[color]
            for i in range(min_r, max_r + 1):
                for j in range(min_c, max_c + 1):
                    if targetGrid[i][j] != color:
                        if color not in graph[targetGrid[i][j]]:
                            graph[targetGrid[i][j]].add(color)
                            indegree[color] += 1

        # Topological sort (Kahn's algorithm)
        q = deque([c for c in colors if indegree[c] == 0])
        visited_count = 0
        while q:
            c = q.popleft()
            visited_count += 1
            for neighbor in graph[c]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    q.append(neighbor)

        return visited_count == len(colors)
