class Solution:
    def shortestSuperstring(self, A: List[str]) -> str:
        n = len(A)

        # Precompute overlap between every pair of strings
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    # maximum overlap where A[i] ends with start of A[j]
                    for k in range(min(len(A[i]), len(A[j])), -1, -1):
                        if A[i][-k:] == A[j][:k]:
                            overlap[i][j] = k
                            break

        # dp[mask][i] = (length, parent_string_index, superstring)
        # mask: set of used strings, i: last string index
        dp = [[(float('inf'), -1, "")] * n for _ in range(1 << n)]

        # Initialize with single strings
        for i in range(n):
            dp[1 << i][i] = (len(A[i]), -1, A[i])

        # Fill dp
        for mask in range(1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue
                cur_len, _, cur_str = dp[mask][last]
                if cur_len == float('inf'):
                    continue
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue
                    new_mask = mask | (1 << nxt)
                    added_len = len(A[nxt]) - overlap[last][nxt]
                    new_len = cur_len + added_len
                    if new_len < dp[new_mask][nxt][0]:
                        new_str = cur_str + A[nxt][overlap[last][nxt]:]
                        dp[new_mask][nxt] = (new_len, last, new_str)

        # Find best result for full mask
        full_mask = (1 << n) - 1
        best_len = float('inf')
        best_str = ""
        for i in range(n):
            length, _, string = dp[full_mask][i]
            if length < best_len:
                best_len = length
                best_str = string

        return best_str
