def maxSatisfied(customers, grumpy, X):
    # Base satisfied customers when owner is not grumpy
    base_satisfied = 0
    n = len(customers)

    for i in range(n):
        if grumpy[i] == 0:
            base_satisfied += customers[i]

    # Find the maximum extra customers we can get by using the technique
    # in a window of size X
    extra = 0
    for i in range(X):
        if grumpy[i] == 1:
            extra += customers[i]

    max_extra = extra
    for i in range(X, n):
        if grumpy[i] == 1:
            extra += customers[i]
        if grumpy[i - X] == 1:
            extra -= customers[i - X]
        max_extra = max(max_extra, extra)

    return base_satisfied + max_extra
