class Solution:
    def splitArraySameAverage(self, A: List[int]) -> bool:
        n = len(A)
        total = sum(A)

        # Early check: if we can have equal averages, then total * k % n == 0 for some k
        possible = False
        for k in range(1, n // 2 + 1):
            if total * k % n == 0:
                possible = True
                break
        if not possible:
            return False

        # DP: dp[s] = set of possible lengths for sum s
        dp = [set() for _ in range(total + 1)]
        dp[0].add(0)

        for num in A:
            for s in range(total, num - 1, -1):
                for length in dp[s - num]:
                    dp[s].add(length + 1)

        for k in range(1, n // 2 + 1):
            if total * k % n == 0:
                target_sum = total * k // n
                if k in dp[target_sum]:
                    return True
        return False
