def atMostNGivenDigitSet(digits, n):
    digits = sorted(digits)
    n_str = str(n)
    len_n = len(n_str)
    count = 0

    # Count all numbers with fewer digits than n
    for i in range(1, len_n):
        count += len(digits) ** i

    # Count numbers with same length as n
    for i, ch in enumerate(n_str):
        # Count numbers where current digit is less than ch
        for d in digits:
            if d < ch:
                count += len(digits) ** (len_n - i - 1)
            else:
                break
        # If current digit not in digits, stop
        if ch not in digits:
            return count

    # If we matched all digits, include n itself
    return count + 1
