        while l <= r:
            if l % 2 == 1:
                left_res = self._merge(left_res, self.tree[l])
                l += 1
            if r % 2 == 0:
                right_res = self._merge(self.tree[r], right_res)
                r -= 1
            l //= 2
            r //= 2
        return self._merge(left_res, right_res)

