    for face in range(6):
        dp[face][1] = 1

    for _ in range(2, n + 1):
        new_dp = [[0] * (max(rollMax) + 1) for _ in range(6)]
        for face in range(6):
            for k in range(1, rollMax[face] + 1):
                if dp[face][k] == 0:
                    continue
                # Continue same face
                if k + 1 <= rollMax[face]:
                    new_dp[face][k + 1] = (new_dp[face][k + 1] + dp[face][k]) % MOD
                # Switch to a different face
                for other_face in range(6):
                    if other_face == face:
                        continue
                    new_dp[other_face][1] = (new_dp[other_face][1] + dp[face][k]) % MOD
        dp = new_dp

