def maxDistance(grid):
    n = len(grid)
    # Initialize queue with all land cells
    queue = deque()
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))

    # If no land or no water, return -1
    if not queue or len(queue) == n * n:
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
