def min_shots(N, L):
    # We need to find the minimal worst-case number of shots
    # using N bullets to determine X in range [1, L].
    # This is a classic egg dropping / bullet problem.
    # dp[i][j] = maximum length we can cover with i bullets and j shots
    dp = [[0] * (L + 1) for _ in range(N + 1)]

    # With 0 shots, we can cover 0 length
    # With 1 bullet and j shots, we can cover j length (linear search)
    for j in range(1, L + 1):
        dp[1][j] = j

    # For more bullets, use recurrence:
    # dp[i][j] = dp[i-1][j-1] + dp[i][j-1] + 1
    for i in range(2, N + 1):
        for j in range(1, L + 1):
            dp[i][j] = dp[i-1][j-1] + dp[i][j-1] + 1

    # Find minimal j such that dp[N][j] >= L
    for j in range(1, L + 1):
        if dp[N][j] >= L:
            return j
    return L

def solve():
    T = int(input().strip())
    for _ in range(T):
        N, L = map(int, input().strip().split())
        print(min_shots(N, L))

if __name__ == "__main__":
    solve()
