We need to find the maximum of the minimum distances between all pairs of cities.  
This is essentially the **maximum edge weight in the Minimum Spanning Tree (MST)** of the graph, because the cheapest route between two cities in a graph is the shortest path, and the maximum of those shortest paths over all pairs is the **diameter of the graph in terms of minimax path** — which equals the largest edge in the MST.

Here’s the Python solution:

```python
import sys
sys.setrecursionlimit(300000)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1
        return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    C = int(next(it))
    F = int(next(it))
    edges = []
    for _ in range(F):
        x = int(next(it)) - 1
        y = int(next(it)) - 1
        p = int(next(it))
        edges.append((p, x, y))

    edges.sort()
    dsu = DSU(C)
    max_cost = 0
    for p, x, y in edges:
        if dsu.union(x, y):
            max_cost = max(max_cost, p)
    print(max_cost)

if __name__ == "__main__":
    main()
```

