def canCross(stones):
    # Map each stone to a set of possible jump sizes that can land on it
    dp = {stone: set() for stone in stones}
    dp[0].add(0)  # Starting point: jump size 0 to reach first stone

    for stone in stones:
        for k in dp[stone]:
            # Possible next jump sizes: k-1, k, k+1
            for jump in (k - 1, k, k + 1):
                if jump > 0 and stone + jump in dp:
                    dp[stone + jump].add(jump)

    # If the last stone has any possible jump size, return True
    return len(dp[stones[-1]]) > 0
