def can_partition(nums: List[int], k: int) -> bool:
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    nums.sort(reverse=True)
    n = len(nums)

    used = [False] * n

    def backtrack(start: int, current_sum: int, remaining_subsets: int) -> bool:
        if remaining_subsets == 0:
            return True
        if current_sum == target:
            return backtrack(0, 0, remaining_subsets - 1)

        for i in range(start, n):
            if not used[i] and current_sum + nums[i] <= target:
                used[i] = True
                if backtrack(i + 1, current_sum + nums[i], remaining_subsets):
                    return True
                used[i] = False
                # Pruning: if current_sum == 0, then nums[i] couldn't be placed, so fail
                if current_sum == 0:
                    return False
                # Pruning: if current_sum + nums[i] == target, then it failed, so fail
                if current_sum + nums[i] == target:
                    return False
        return False

    return backtrack(0, 0, k)

