def max_score(matrix, m, n):
    # Step 1: Ensure the first column is all 1's by toggling rows if needed
    for i in range(m):
        if matrix[i][0] == 0:
            # toggle entire row
            for j in range(n):
                matrix[i][j] ^= 1

    # Step 2: For each column after the first, decide whether to toggle to maximize sum
    for j in range(1, n):
        count_ones = 0
        for i in range(m):
            if matrix[i][j] == 1:
                count_ones += 1
        # If fewer than half are 1, toggle the column
        if count_ones < m - count_ones:
            for i in range(m):
                matrix[i][j] ^= 1

    # Step 3: Calculate the total score
    total = 0
    for i in range(m):
        row_val = 0
        for j in range(n):
            row_val = (row_val << 1) | matrix[i][j]
        total += row_val
    return total

