def findKthBit(n: int, k: int) -> str:
    # Recursive function to find the kth bit in Sn
    def helper(n, k):
        if n == 1:
            return "0"
        length = (1 << n) - 1  # 2^n - 1
        mid = (length // 2) + 1  # middle position (1-indexed)
        if k == mid:
            return "1"
        elif k < mid:
            return helper(n - 1, k)
        else:
            # k > mid: find corresponding bit in inverted reversed S_{n-1}
            mirrored_k = length - k + 1
            bit = helper(n - 1, mirrored_k)
            return "0" if bit == "1" else "1"

    return helper(n, k)
