    def findMinStep(self, board: str, hand: str) -> int:
        # Count balls in hand
        hand_count = [0] * 5
        colors = {'R':0, 'Y':1, 'B':2, 'G':3, 'W':4}
        for c in hand:
            hand_count[colors[c]] += 1

        @lru_cache(None)
        def dfs(board_tuple, hand_tuple):
