                    while j < len(board) and board[j] == board[i]:
                        j += 1
                    if j - i >= 3:
                        changed = True
                        i = j
                        continue
                    new_board.extend(board[i:j])
                    i = j
                board = new_board

            if not board:
                return 0

            hand = list(hand_tuple)
            # If no balls left in hand, impossible
            if sum(hand) == 0:
