from typing import List

class Solution:
    def stoneGameIII(self, stoneValue: List[int]) -> str:
        n = len(stoneValue)
        # dp[i] = maximum net advantage (Alice score - Bob score) for the current player
        # starting from pile i
        dp = [0] * (n + 3)  # extra space to avoid index errors

        for i in range(n - 1, -1, -1):
            best = float('-inf')
            take = 0
            for k in range(1, 4):
                if i + k - 1 < n:
                    take += stoneValue[i + k - 1]
                    # current player gets 'take' and then opponent gets dp[i+k] advantage
                    best = max(best, take - dp[i + k])
            dp[i] = best

        if dp[0] > 0:
            return "Alice"
        elif dp[0] < 0:
            return "Bob"
        else:
            return "Tie"
