        if i + 2 <= N:
            dp_forward[i + 2] = max(dp_forward[i + 2], dp_forward[i] + arr[i + 2])

    # dp_backward[i] = max score to reach 1 from i moving only backward (i >= 1)
    dp_backward = [-10**9] * (N + 1)
