def new21Game(N: int, K: int, W: int) -> float:
    if K == 0:
        return 1.0
    dp = [0.0] * (K + W)
    dp[0] = 1.0
    window_sum = 1.0
    for i in range(1, K + W):
        dp[i] = window_sum / W
        if i < K:
            window_sum += dp[i]
        if i - W >= 0:
            window_sum -= dp[i - W]
    return sum(dp[K: N + 1])
