        x12 = int(input_data[idx+2]); y12 = int(input_data[idx+3])
        idx += 4
        x21 = int(input_data[idx]); y21 = int(input_data[idx+1])
        x22 = int(input_data[idx+2]); y22 = int(input_data[idx+3])
        idx += 4

        # Normalize snake1: ensure start <= end in reading order
        if (x11 == x12 and y11 > y12) or (y11 == y12 and x11 > x12):
            x11, y11, x12, y12 = x12, y12, x11, y11
        # Normalize snake2
        if (x21 == x22 and y21 > y22) or (y21 == y22 and x21 > x22):
            x21, y21, x22, y22 = x22, y22, x21, y21

        # Build set of cells for each snake
        cells1 = set()
        if x11 == x12:
            for y in range(y11, y12+1):
                cells1.add((x11, y))
        else:
            for x in range(x11, x12+1):
                cells1.add((x, y11))

        cells2 = set()
        if x21 == x22:
            for y in range(y21, y22+1):
                cells2.add((x21, y))
        else:
            for x in range(x21, x22+1):
                cells2.add((x, y21))

        union_cells = cells1 | cells2

        # Build adjacency list for union cells
        adj = {cell: [] for cell in union_cells}
        # Add edges from snake1
        if x11 == x12:
            for y in range(y11, y12):
                a = (x11, y)
                b = (x11, y+1)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)
        else:
            for x in range(x11, x12):
                a = (x, y11)
                b = (x+1, y11)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

        # Add edges from snake2
        if x21 == x22:
