                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

        # Check degree condition
        degree_ok = True
        for cell in adj:
            if len(adj[cell]) > 2:
                degree_ok = False
                break
        if not degree_ok:
            results.append("no")
