                cells2.add((x21, y))
        else:
            for x in range(x21, x22+1):
                cells2.add((x, y21))

        union_cells = cells1 | cells2

        # Build adjacency list for union cells
        adj = {cell: [] for cell in union_cells}
        # Add edges from snake1
        if x11 == x12:
            for y in range(y11, y12):
                a = (x11, y)
                b = (x11, y+1)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)
        else:
            for x in range(x11, x12):
                a = (x, y11)
                b = (x+1, y11)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

        # Add edges from snake2
        if x21 == x22:
            for y in range(y21, y22):
                a = (x21, y)
                b = (x21, y+1)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)
        else:
            for x in range(x21, x22):
                a = (x, y21)
                b = (x+1, y21)
                if a in adj and b in adj:
                    adj[a].append(b)
                    adj[b].append(a)

        # Check degree condition
        degree_ok = True
        for cell in adj:
            if len(adj[cell]) > 2:
                degree_ok = False
                break
        if not degree_ok:
            results.append("no")
            continue

        # Check connectivity: union must be a single connected component
        if not union_cells:
            results.append("no")
            continue

        start = next(iter(union_cells))
        stack = [start]
        visited = {start}
        while stack:
            cur = stack.pop()
            for nb in adj[cur]:
                if nb not in visited:
                    visited.add(nb)
                    stack.append(nb)
        if len(visited) != len(union_cells):
            results.append("no")
        else:
            results.append("yes")

    sys.stdout.write("\n".join(results))

