def maxWidthRamp(A):
    # Build a stack of indices with decreasing values
    stack = []
    for i, val in enumerate(A):
        if not stack or val < A[stack[-1]]:
            stack.append(i)

    max_width = 0
    # Traverse from the end to find maximum width
