def getLengthOfOptimalCompression(s: str, k: int) -> int:
    n = len(s)
    # dp[i][k] = minimum compressed length for s[i:] with at most k deletions
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[n] = [0] * (k + 1)  # empty string

    for i in range(n - 1, -1, -1):
        for rem in range(k + 1):
            # Option 1: delete current character
            if rem > 0:
                dp[i][rem] = min(dp[i][rem], dp[i + 1][rem - 1])

            # Option 2: keep current character and compress the run
            # count how many same characters we can keep
            same_count = 0
            delete_count = 0
            for j in range(i, n):
                if s[j] == s[i]:
                    same_count += 1
                else:
                    delete_count += 1

                if delete_count > rem:
                    break

                # length of encoding for this run
                if same_count == 1:
                    encoded_len = 1
                elif same_count < 10:
                    encoded_len = 2
                elif same_count < 100:
                    encoded_len = 3
                else:
                    encoded_len = 4

                dp[i][rem] = min(dp[i][rem], encoded_len + dp[j + 1][rem - delete_count])

    return dp[0][k]
