class Solution:
    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [0] * n
        dq = deque()

        for i in range(n):
            # Remove indices that are out of the window (distance > k)
            while dq and dq[0] < i - k:
                dq.popleft()

            # dp[i] = nums[i] + max(0, dp[dq[0]]) if dq else nums[i]
            dp[i] = nums[i]
            if dq:
                dp[i] = max(dp[i], nums[i] + dp[dq[0]])

            # Maintain deque in decreasing order of dp values
            while dq and dp[dq[-1]] <= dp[i]:
                dq.pop()

            # Only add to deque if dp[i] > 0, because negative prefix won't help
            if dp[i] > 0:
                dq.append(i)
            else:
                # We still need to consider negative values if all are negative
                # So we add anyway but with the value itself
                dq.append(i)

        return max(dp)
