def largestMultipleOfThree(digits):
    total = sum(digits)
    count = [0] * 10
    for d in digits:
        count[d] += 1

    # Sort digits in descending order to form largest number
    digits.sort(reverse=True)

    # If total sum is divisible by 3, we can use all digits
    if total % 3 == 0:
        if digits[0] == 0:
            return "0"
        return ''.join(map(str, digits))

    # We need to remove the smallest possible digits to make sum divisible by 3
    remainder = total % 3

    # Try to remove one digit with remainder == remainder
    removed = False
    for i in range(remainder, 10, 3):
        if count[i] > 0:
            count[i] -= 1
            removed = True
            break

    # If not possible, remove two digits with remainder 3 - remainder
    if not removed:
        target = 3 - remainder
        removed_count = 0
        for i in range(target, 10, 3):
            while count[i] > 0 and removed_count < 2:
                count[i] -= 1
                removed_count += 1
        if removed_count < 2:
            return ""

    # Build result from remaining digits
    result = []
    for d in range(9, -1, -1):
        result.extend([str(d)] * count[d])

    if not result:
        return ""
    if result[0] == '0':
        return "0"
    return ''.join(result)
