from typing import List

class Solution:
    def rankTeams(self, votes: List[str]) -> str:
        if not votes:
            return ""

        # Number of teams
        num_teams = len(votes[0])

        # Initialize vote counts: dict mapping team -> list of counts per position
        vote_count = {team: [0] * num_teams for team in votes[0]}

        # Count votes for each position
        for vote in votes:
            for pos, team in enumerate(vote):
                vote_count[team][pos] -= 1  # negative for descending sort

        # Sort teams: first by vote counts (most first-place votes, etc.), then alphabetically
        sorted_teams = sorted(vote_count.keys(), key=lambda team: (vote_count[team], team))

        return ''.join(sorted_teams)
