from typing import List

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        MOD = 10**9 + 7
        n = len(hats)

        # Map each hat to the list of people who prefer it
        hat_to_people = [[] for _ in range(41)]
        for person, preferred_hats in enumerate(hats):
            for hat in preferred_hats:
                hat_to_people[hat].append(person)

        # dp[mask] = number of ways to assign hats to people represented by mask
        dp = [0] * (1 << n)
        dp[0] = 1

        for hat in range(1, 41):
            # For each hat, we try to assign it to one of the people who like it
            # We iterate masks in reverse to avoid using the same hat multiple times
            for mask in range((1 << n) - 1, -1, -1):
                if dp[mask] == 0:
                    continue
                for person in hat_to_people[hat]:
                    if not (mask & (1 << person)):
                        new_mask = mask | (1 << person)
                        dp[new_mask] = (dp[new_mask] + dp[mask]) % MOD

        return dp[(1 << n) - 1]
```

