            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for _ in range(m):
            a = int(next(it))
            b = int(next(it))
            union(a, b)

        q = int(next(it))
        for _ in range(q):
            x = int(next(it))
            y = int(next(it))
            if find(x) == find(y):
                out_lines.append("YO")
            else:
                out_lines.append("NO")

    sys.stdout.write("\n".join(out_lines))

