        fail = [0] * (m + 1)
        j = 0
        for i in range(1, m):
            while j > 0 and evil[i] != evil[j]:
                j = fail[j]
            if evil[i] == evil[j]:
                j += 1
            fail[i + 1] = j

        # dp[pos][matched][tight_low][tight_high]
        dp = [[[[-1] * 2 for _ in range(2)] for _ in range(m)] for _ in range(n)]

        def dfs(pos, matched, tight_low, tight_high):
            if matched == m:
                return 0
            if pos == n:
                return 1
            if dp[pos][matched][tight_low][tight_high] != -1:
                return dp[pos][matched][tight_low][tight_high]

            low_char = s1[pos] if tight_low else 'a'
            high_char = s2[pos] if tight_high else 'z'

            res = 0
            for c in range(ord(low_char), ord(high_char) + 1):
                ch = chr(c)
                ntight_low = tight_low and (ch == s1[pos])
                ntight_high = tight_high and (ch == s2[pos])

                # Update matched state using KMP
                nmatched = matched
