from collections import defaultdict, deque
from typing import List

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], S: int, T: int) -> int:
        if S == T:
            return 0

        # Map each stop to the list of bus indices that serve it
        stop_to_buses = defaultdict(list)
        for bus_idx, stops in enumerate(routes):
            for stop in stops:
                stop_to_buses[stop].append(bus_idx)

        # BFS over buses
        visited_buses = set()
        visited_stops = {S}
        queue = deque()

        # Start from all buses that serve S
        for bus in stop_to_buses[S]:
            visited_buses.add(bus)
            queue.append((bus, 1))  # (bus_index, number_of_buses_taken)

        while queue:
            bus, dist = queue.popleft()
            # Check all stops on this bus
            for stop in routes[bus]:
                if stop == T:
                    return dist
                if stop not in visited_stops:
                    visited_stops.add(stop)
                    # Add all unvisited buses serving this stop
                    for next_bus in stop_to_buses[stop]:
                        if next_bus not in visited_buses:
                            visited_buses.add(next_bus)
                            queue.append((next_bus, dist + 1))

        return -1
```

