def minSwaps(grid):
    n = len(grid)
    # For each row, find the rightmost 1's column index
    rightmost_one = []
    for i in range(n):
        pos = -1
        for j in range(n):
            if grid[i][j] == 1:
                pos = j
        rightmost_one.append(pos)

    # We need row i to have rightmost_one <= i for it to be valid above diagonal
    # So we need to sort rows by moving them up so that rightmost_one[i] <= i

    swaps = 0
    for i in range(n):
        # Find the first row from i downwards that satisfies rightmost_one <= i
        target = -1
        for k in range(i, n):
            if rightmost_one[k] <= i:
                target = k
                break
        if target == -1:
            return -1
        # Bring that row up to position i by swapping adjacent rows
        for k in range(target, i, -1):
            rightmost_one[k], rightmost_one[k-1] = rightmost_one[k-1], rightmost_one[k]
            swaps += 1
    return swaps
