def clumsy(N: int) -> int:
    if N == 1:
        return 1
    if N == 2:
        return 2 * 1
    if N == 3:
        return 3 * 2 // 1

    # First group: N * (N-1) // (N-2) + (N-3)
    result = N * (N - 1) // (N - 2) + (N - 3)
    N -= 4

    # Remaining groups: - a * b // c + d
    while N >= 4:
        result -= N * (N - 1) // (N - 2)
        result += (N - 3)
        N -= 4

    # Handle remaining numbers (1 to 3)
    if N == 3:
        result -= 3 * 2 // 1
    elif N == 2:
        result -= 2 * 1
    elif N == 1:
        result -= 1

    return result
