def numDupDigitsAtMostN(N: int) -> int:
    # Count numbers with no repeated digits up to N
    # Then answer = N - count_no_repeat

    digits = list(map(int, str(N + 1)))  # work with N+1 to handle inclusive
    n = len(digits)

    # Count numbers with fewer digits (all have no leading zero)
    count_no_repeat = 0
    for i in range(1, n):
        count_no_repeat += 9 * perm(9, i - 1)

    # Count numbers with same number of digits
    seen = set()
    for i, d in enumerate(digits):
        start = 0 if i > 0 else 1  # first digit cannot be 0
        for x in range(start, d):
            if x not in seen:
                count_no_repeat += perm(9 - i, n - i - 1)
        if d in seen:
            break
        seen.add(d)
    else:
        # If we never broke, N+1 itself has no repeated digits
        count_no_repeat += 1

    return N - count_no_repeat

def perm(m: int, k: int) -> int:
