class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        # Find the root: node with no parent
        has_parent = [False] * n
        for i in range(n):
            if leftChild[i] != -1:
                has_parent[leftChild[i]] = True
            if rightChild[i] != -1:
                has_parent[rightChild[i]] = True

        root = -1
        for i in range(n):
            if not has_parent[i]:
                if root == -1:
                    root = i
                else:
                    return False  # More than one root

        if root == -1:
            return False  # No root (cycle)

        # BFS/DFS to check connectivity and no cycles
        visited = [False] * n
        stack = [root]
        visited[root] = True
        count = 0

        while stack:
            node = stack.pop()
            count += 1
            for child in (leftChild[node], rightChild[node]):
                if child != -1:
                    if visited[child]:
