def findReplaceString(S: str, indexes: list[int], sources: list[str], targets: list[str]) -> str:
    # Sort operations by index in descending order to avoid index shifting issues
    combined = sorted(zip(indexes, sources, targets), reverse=True)

    for i, src, tgt in combined:
