def army_power(N):
    # The power of the army is the number of integers from 1 to N
    # that are powers of a prime number.
    # We can precompute primes up to N using a simple sieve.
    if N < 2:
        return 0

    is_prime = [True] * (N + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(N**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, N+1, i):
                is_prime[j] = False

    primes = [i for i, val in enumerate(is_prime) if val]

    count = 0
    for p in primes:
        power = p * p
        while power <= N:
            count += 1
            power *= p
    return count

if __name__ == "__main__":
    N = int(input().strip())
    print(army_power(N))
