def primePalindrome(N: int) -> int:
    def is_prime(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    def reverse(x):
        rev = 0
        while x:
            rev = rev * 10 + x % 10
            x //= 10
        return rev

    # Special case for even-length palindromes > 11: they are divisible by 11
    if 8 <= N <= 11:
        return 11

    # Generate palindromes of odd length
    for length in range(1, 10):
        # Generate all numbers with half length
        half_start = 10 ** ((length - 1) // 2)
        half_end = 10 ** ((length + 1) // 2)
        for root in range(half_start, half_end):
            s = str(root)
            # Build palindrome
            pal = int(s + s[-2::-1])
            if pal >= N and is_prime(pal):
                return pal

    return -1
