class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        n = len(jobDifficulty)
        if n < d:
            return -1

        # dp[i][j] = min difficulty to schedule first j+1 jobs in i+1 days
        dp = [[float('inf')] * n for _ in range(d)]

        # Base case: 1 day
        max_difficulty = 0
        for j in range(n):
            max_difficulty = max(max_difficulty, jobDifficulty[j])
            dp[0][j] = max_difficulty

        # Fill dp for days 2 to d
        for i in range(1, d):
            for j in range(i, n):
                max_difficulty = 0
                for k in range(j, i - 1, -1):
                    max_difficulty = max(max_difficulty, jobDifficulty[k])
                    dp[i][j] = min(dp[i][j], dp[i-1][k-1] + max_difficulty)

        return dp[d-1][n-1]
