        for j in range(n):
            if grid[i][j] == '/':
                expanded[3*i][3*j+2] = 1
                expanded[3*i+1][3*j+1] = 1
                expanded[3*i+2][3*j] = 1
            elif grid[i][j] == '\\':
                expanded[3*i][3*j] = 1
                expanded[3*i+1][3*j+1] = 1
                expanded[3*i+2][3*j+2] = 1

    # DFS to count regions
    def dfs(x, y):
        if x < 0 or x >= 3*n or y < 0 or y >= 3*n or expanded[x][y] != 0:
