class Solution:
    def isEscapePossible(self, blocked: List[List[int]], source: List[int], target: List[int]) -> bool:
        # If there are few blocked cells, we can BFS with a limited boundary.
        # The maximum area blocked cells can enclose is at most (len(blocked)*(len(blocked)-1)//2)
        # So we limit BFS to that many steps from source and target.
        if not blocked:
            return True

