def findTargetSumWays(nums, S):
    total_sum = sum(nums)

    # If S is out of possible range, return 0
    if S > total_sum or S < -total_sum:
        return 0

    # dp[offset + sum] = number of ways to achieve that sum
    offset = total_sum
    dp = [0] * (2 * total_sum + 1)
    dp[offset] = 1  # 0 sum initially

    for num in nums:
        next_dp = [0] * (2 * total_sum + 1)
        for s in range(-total_sum, total_sum + 1):
            if dp[offset + s] > 0:
                # add +
                if s + num <= total_sum:
                    next_dp[offset + s + num] += dp[offset + s]
                # add -
                if s - num >= -total_sum:
                    next_dp[offset + s - num] += dp[offset + s]
        dp = next_dp

    return dp[offset + S]
