class Solution:
    def maxSizeSlices(self, slices: List[int]) -> int:
        n = len(slices)
        k = n // 3

        def max_sum(arr: List[int]) -> int:
            m = len(arr)
            # dp[i][j] = max sum using first i elements and picking j slices
            dp = [[0] * (k + 1) for _ in range(m + 1)]
            for i in range(1, m + 1):
                for j in range(1, k + 1):
                    if i == 1:
                        dp[i][j] = arr[0] if j == 1 else 0
                    else:
                        dp[i][j] = max(dp[i-1][j], dp[i-2][j-1] + arr[i-1])
            return dp[m][k]

        # Case 1: exclude last element
        case1 = max_sum(slices[:-1])
        # Case 2: exclude first element
        case2 = max_sum(slices[1:])

        return max(case1, case2)
