from collections import deque
from typing import List

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j]:
                    start |= (1 << (i * n + j))

        if start == 0:
            return 0

        queue = deque([start])
        visited = {start: 0}

        while queue:
            state = queue.popleft()
            steps = visited[state]

            for i in range(m):
                for j in range(n):
                    next_state = state
                    # flip (i, j)
                    next_state ^= (1 << (i * n + j))
                    # flip neighbors
                    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < m and 0 <= nj < n:
                            next_state ^= (1 << (ni * n + nj))

                    if next_state == 0:
                        return steps + 1

                    if next_state not in visited:
                        visited[next_state] = steps + 1
                        queue.append(next_state)

        return -1
