from typing import List

class Solution:
    def maxSumTwoNoOverlap(self, A: List[int], L: int, M: int) -> int:
        n = len(A)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + A[i]

        # max sum of L-length subarray to the left of current position
        maxL_left = [0] * n
        # max sum of M-length subarray to the left of current position
        maxM_left = [0] * n

        # Compute maxL_left: max sum of L-length subarray ending at or before i
        for i in range(n):
            if i >= L - 1:
                sumL = prefix[i+1] - prefix[i+1-L]
                if i == L - 1:
                    maxL_left[i] = sumL
                else:
                    maxL_left[i] = max(maxL_left[i-1], sumL)
            else:
                maxL_left[i] = 0

        # Compute maxM_left: max sum of M-length subarray ending at or before i
        for i in range(n):
            if i >= M - 1:
                sumM = prefix[i+1] - prefix[i+1-M]
                if i == M - 1:
                    maxM_left[i] = sumM
                else:
                    maxM_left[i] = max(maxM_left[i-1], sumM)
            else:
                maxM_left[i] = 0

        # max sum of L-length subarray to the right of current position
        maxL_right = [0] * n
        # max sum of M-length subarray to the right of current position
        maxM_right = [0] * n

        # Compute maxL_right: max sum of L-length subarray starting at or after i
        for i in range(n-1, -1, -1):
            if i <= n - L:
                sumL = prefix[i+L] - prefix[i]
                if i == n - L:
                    maxL_right[i] = sumL
                else:
                    maxL_right[i] = max(maxL_right[i+1], sumL)
            else:
                maxL_right[i] = 0

        # Compute maxM_right: max sum of M-length subarray starting at or after i
        for i in range(n-1, -1, -1):
            if i <= n - M:
                sumM = prefix[i+M] - prefix[i]
                if i == n - M:
                    maxM_right[i] = sumM
                else:
                    maxM_right[i] = max(maxM_right[i+1], sumM)
            else:
                maxM_right[i] = 0

        ans = 0
        # Case 1: L before M
        # L ends at i, M starts at i+1
        for i in range(L-1, n-M):
            ans = max(ans, maxL_left[i] + maxM_right[i+1])

        # Case 2: M before L
        # M ends at i, L starts at i+1
        for i in range(M-1, n-L):
            ans = max(ans, maxM_left[i] + maxL_right[i+1])

