import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        grid = []
        for _ in range(n):
            row_str = next(it).strip()
            # Convert string of '0'/'1' to list of ints
            grid.append([int(ch) for ch in row_str])

        # Precompute: rows that contain at least one 1
        row_has_one = [False] * n
        col_has_one = [False] * m
        any_one = False
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    row_has_one[i] = True
                    col_has_one[j] = True
                    any_one = True

        # If no 1 at all, everything is impossible
        if not any_one:
            for i in range(n):
                out_lines.append(" ".join(["-1"] * m))
            continue

        # Precompute distances to nearest row with a 1
        INF = 10**9
        row_dist = [INF] * n
        # left to right
        last = -INF
        for i in range(n):
            if row_has_one[i]:
                last = i
            row_dist[i] = min(row_dist[i], i - last)
        # right to left
        last = INF
        for i in range(n-1, -1, -1):
            if row_has_one[i]:
                last = i
            row_dist[i] = min(row_dist[i], last - i)

        # Precompute distances to nearest column with a 1
        col_dist = [INF] * m
        last = -INF
        for j in range(m):
            if col_has_one[j]:
                last = j
            col_dist[j] = min(col_dist[j], j - last)
        last = INF
        for j in range(m-1, -1, -1):
            if col_has_one[j]:
                last = j
            col_dist[j] = min(col_dist[j], last - j)

        # Answer for each cell
        for i in range(n):
            row_ans = []
            for j in range(m):
                if grid[i][j] == 1:
                    row_ans.append("0")
                else:
                    # Need at least one move: either from a row with 1 or column with 1
                    # If there is a 1 in same row or same column, answer is 1
                    if row_has_one[i] or col_has_one[j]:
                        row_ans.append("1")
                    else:
                        # Need two moves: bring a 1 to the row and then to the column
                        # distance to nearest row with 1 + distance to nearest column with 1
                        d = row_dist[i] + col_dist[j]
                        if d >= INF:
                            row_ans.append("-1")
                        else:
                            row_ans.append(str(d))
            out_lines.append(" ".join(row_ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
