def getHappyString(n: int, k: int) -> str:
    # Total number of happy strings of length n is 3 * 2^(n-1)
    total = 3 * (1 << (n - 1))  # 2^(n-1) using bit shift
    if k > total:
        return ""

    # We'll build the string character by character
    result = []
    # The first character choices: 'a', 'b', 'c'
    choices = ['a', 'b', 'c']

    # For each position, we decide which character to pick
    for i in range(n):
        # Number of strings starting with each possible character at this position
        if i == 0:
            block_size = 1 << (n - 1)  # 2^(n-1)
        else:
            block_size = 1 << (n - i - 1)  # 2^(n-i-1)

        for ch in choices:
            if k > block_size:
                k -= block_size
            else:
                result.append(ch)
                # Update choices for next position: exclude the last chosen character
                choices = [c for c in ['a', 'b', 'c'] if c != ch]
                break

    return ''.join(result)
