    MAX_N = 30
    MAX_M = 30
    MAX_K = 50
    INF = 10**9

    # dp[n][m][k] = min cost to get exactly k squares from n x m bar
    dp = [[[INF] * (MAX_K + 1) for _ in range(MAX_M + 1)] for _ in range(MAX_N + 1)]

    for n in range(1, MAX_N + 1):
        for m in range(1, MAX_M + 1):
            total = n * m
            max_k = min(total, MAX_K)
            # Base: if k == 0 or k == total, cost = 0
            dp[n][m][0] = 0
            if total <= MAX_K:
                dp[n][m][total] = 0
            # For other k, try all possible breaks
            for k in range(1, max_k + 1):
                if k == total:
                    continue
                # Horizontal breaks
                for i in range(1, n):
                    cost = m * m
                    # left piece i x m, right piece (n-i) x m
                    for k1 in range(0, k + 1):
                        k2 = k - k1
                        if k1 <= i * m and k2 <= (n - i) * m:
                            dp[n][m][k] = min(dp[n][m][k], dp[i][m][k1] + dp[n - i][m][k2] + cost)
