def longestSubstring(s: str, k: int) -> int:
    if len(s) < k:
        return 0

    # Count frequency of each character
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    # Find characters that appear less than k times
    for ch, count in freq.items():
        if count < k:
            # Split the string at this character and recursively solve
            result = 0
            for substring in s.split(ch):
                result = max(result, longestSubstring(substring, k))
            return result

    # If all characters appear at least k times, the whole string is valid
    return len(s)
