from math import isqrt

class Solution:
    def numSquarefulPerms(self, A):
        n = len(A)
        count = Counter(A)

        # Build adjacency: which numbers can follow a given number
        adj = {x: [] for x in count}
        for x in count:
            for y in count:
                s = x + y
                r = isqrt(s)
                if r * r == s:
                    adj[x].append(y)

        # backtracking with memoization on (last, used_counts_tuple)
        def backtrack(last, remaining):
            if sum(remaining.values()) == 0:
                return 1
            total = 0
            for nxt in adj[last]:
                if remaining[nxt] > 0:
                    remaining[nxt] -= 1
                    total += backtrack(nxt, remaining)
                    remaining[nxt] += 1
            return total

        ans = 0
        for start in list(count.keys()):
            if count[start] > 0:
                count[start] -= 1
                ans += backtrack(start, count)
                count[start] += 1

        return ans
