def tilingRectangle(n: int, m: int) -> int:
    # If dimensions are equal, one square suffices
    if n == m:
        return 1

    # Ensure n is the smaller dimension for easier handling
    if n > m:
        n, m = m, n

    # dp[i][j] = minimum squares to tile i x j rectangle
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]

    # Base case: 1 x k or k x 1 needs k squares
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i == j:
                dp[i][j] = 1
            else:
                # Try vertical cuts
                for k in range(1, i):
                    dp[i][j] = min(dp[i][j], dp[k][j] + dp[i - k][j])
                # Try horizontal cuts
                for k in range(1, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[i][j - k])

    return dp[n][m]

# Example usage
if __name__ == "__main__":
