def minimumSwap(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1

    xy = 0  # count of positions where s1[i]='x', s2[i]='y'
    yx = 0  # count of positions where s1[i]='y', s2[i]='x'

    for c1, c2 in zip(s1, s2):
        if c1 == 'x' and c2 == 'y':
            xy += 1
        elif c1 == 'y' and c2 == 'x':
            yx += 1

    # If total mismatches is odd, impossible
    if (xy + yx) % 2 != 0:
        return -1

    # Each pair of xy can be fixed with 1 swap, same for yx
    # Remaining one xy and one yx need 2 swaps
    return xy // 2 + yx // 2 + (xy % 2) * 2
