def findSubstringInWraproundString(p: str) -> int:
    # dp[c] = max length of contiguous substring ending with character c
    dp = {chr(ord('a') + i): 0 for i in range(26)}
    max_len = 0

    for i, ch in enumerate(p):
        if i > 0 and (ord(ch) - ord(p[i-1]) == 1 or (p[i-1] == 'z' and ch == 'a')):
            max_len += 1
        else:
            max_len = 1
        dp[ch] = max(dp[ch], max_len)

    return sum(dp.values())
