def countTriplets(A):
    # Since A[i] < 2^16, we can use a frequency map for pairs
    from collections import Counter

    # Count frequencies of each number
    freq = Counter(A)

    # Count pairs (i, j) such that A[i] & A[j] == value
    pair_count = Counter()
    for x in freq:
        for y in freq:
            pair_count[x & y] += freq[x] * freq[y]

    # Count triples
    ans = 0
    for z in freq:
        for pair_val, cnt in pair_count.items():
            if (z & pair_val) == 0:
                ans += cnt * freq[z]

    return ans
