def unhappyFriends(n: int, preferences, pairs) -> int:
    # Build a preference rank matrix: rank[i][j] = how much i prefers j (lower is better)
    rank = [[0] * n for _ in range(n)]
    for i in range(n):
        for idx, j in enumerate(preferences[i]):
            rank[i][j] = idx

    # Build a mapping from person to their partner
    partner = {}
    for x, y in pairs:
        partner[x] = y
        partner[y] = x

    unhappy_count = 0

    # Check each person
    for x in range(n):
        y = partner[x]
        # For each person u that x prefers over y
        for u in preferences[x]:
            if u == y:
                break
            v = partner[u]
            # Check if u prefers x over v
            if rank[u][x] < rank[u][v]:
                unhappy_count += 1
                break

    return unhappy_count
